INSERT INTO prompts (title, description, content, main_category, sub_category, usage_count, user_id) VALUES
('小红书爆款标题生成', '生成吸引点击的小红书风格标题，包含emoji和情绪词。', '{"template": "请为主题“${topic}”生成5个小红书爆款标题。要求：\n1. 包含emoji表情\n2. 语气${tone}\n3. 突出痛点或爽点\n4. 吸引点击", "fields": [{"id": "topic", "label": "主题", "type": "text", "placeholder": "例如：夏季防晒"}, {"id": "tone", "label": "语气", "type": "text", "placeholder": "例如：真诚分享、震惊体"}]}', 'marketing', 'social_media', 1200, 'system'),
('朋友圈营销文案', '适用于微商或个人IP的朋友圈软广文案。', '{"template": "请写一条朋友圈营销文案。产品是“${product}”。目标受众是${audience}。要求：\n1. 生活化切入\n2. 软性植入产品优势\n3. 结尾引导互动或咨询", "fields": [{"id": "product", "label": "产品", "type": "text"}, {"id": "audience", "label": "受众", "type": "text"}]}', 'marketing', 'social_media', 850, 'system'),
('短视频口播脚本', '生成抖音/快手风格的短视频口播脚本，包含分镜描述。', '{"template": "请写一个关于“${topic}”的短视频口播脚本。时长约${duration}秒。风格：${style}。请包含：\n1. 黄金3秒开头\n2. 中间干货/反转\n3. 结尾引导关注", "fields": [{"id": "topic", "label": "主题", "type": "text"}, {"id": "duration", "label": "时长(秒)", "type": "number"}, {"id": "style", "label": "风格", "type": "text"}]}', 'marketing', 'video_script', 2300, 'system'),
('电商产品详情页文案', '生成淘宝/京东详情页的卖点文案，包含痛点直击和产品优势。', '{"template": "请为产品“${product}”撰写详情页文案。核心卖点是：${selling_points}。请包含：\n1. 用户痛点场景\n2. 产品解决方案\n3. 信任背书\n4. 促销紧迫感", "fields": [{"id": "product", "label": "产品名称", "type": "text"}, {"id": "selling_points", "label": "核心卖点", "type": "textarea"}]}', 'marketing', 'e_commerce', 1500, 'system'),
('品牌Slogan生成', '为品牌或活动生成朗朗上口、易于传播的Slogan。', '{"template": "请为品牌“${brand}”生成10个Slogan。品牌定位是：${positioning}。要求：\n1. 简短有力\n2. 朗朗上口\n3. 传达品牌核心价值", "fields": [{"id": "brand", "label": "品牌名称", "type": "text"}, {"id": "positioning", "label": "品牌定位", "type": "textarea"}]}', 'marketing', 'slogan', 600, 'system'),
('EDM邮件营销', '撰写高转化率的营销邮件。', '{"template": "请写一封营销邮件。目的：${goal}。收件人：${recipient}。要求：\n1. 标题吸引打开\n2. 正文简洁，利益点明确\n3. 清晰的CTA（行动号召）", "fields": [{"id": "goal", "label": "营销目的", "type": "text", "placeholder": "例如：新品推广、召回老用户"}, {"id": "recipient", "label": "收件人特征", "type": "text"}]}', 'marketing', 'email', 400, 'system');
INSERT INTO prompts (title, description, content, main_category, sub_category, usage_count, user_id) VALUES
('二次元动漫少女', '生成高质量的二次元动漫美少女，光影细腻。', '{"template": "Masterpiece, best quality, ultra-detailed, anime style, 1girl, ${appearance}, ${clothing}, ${action}, ${background}, soft lighting, cinematic composition", "fields": [{"id": "appearance", "label": "外貌特征", "type": "text", "placeholder": "例如：silver hair, blue eyes"}, {"id": "clothing", "label": "服装", "type": "text"}, {"id": "action", "label": "动作", "type": "text"}, {"id": "background", "label": "背景", "type": "text"}]}', 'image', 'anime', 5000, 'system'),
('赛博朋克城市', '生成未来感十足的赛博朋克风格城市景观。', '{"template": "Cyberpunk city, night, neon lights, rain, futuristic buildings, flying cars, high contrast, ${details}, 8k resolution, unreal engine 5 render", "fields": [{"id": "details", "label": "细节描述", "type": "textarea", "placeholder": "例如：busy street, holograms"}]}', 'image', 'cyberpunk', 3200, 'system'),
('写实人像摄影', '生成逼真的写实风格人像，类似单反拍摄效果。', '{"template": "Photorealistic portrait of ${subject}, shot on 85mm lens, f/1.8, natural lighting, highly detailed skin texture, ${environment}, 8k, raw photo", "fields": [{"id": "subject", "label": "人物描述", "type": "text"}, {"id": "environment", "label": "环境", "type": "text"}]}', 'image', 'realistic', 4100, 'system'),
('水彩风景画', '生成清新淡雅的水彩风格风景画。', '{"template": "Watercolor painting of ${scene}, soft colors, artistic style, wet on wet technique, ${mood}, masterpiece", "fields": [{"id": "scene", "label": "场景", "type": "text"}, {"id": "mood", "label": "氛围", "type": "text"}]}', 'image', 'watercolor', 1800, 'system'),
('3D可爱盲盒公仔', '生成类似泡泡玛特的3D可爱公仔风格。', '{"template": "3D render, blind box toy style, cute chibi character, ${character}, ${clothing}, studio lighting, pastel colors, clay texture, c4d, octane render", "fields": [{"id": "character", "label": "角色特征", "type": "text"}, {"id": "clothing", "label": "服装", "type": "text"}]}', 'image', '3d_render', 2500, 'system'),
('国风水墨山水', '生成中国传统水墨风格的山水画。', '{"template": "Chinese ink wash painting, shan shui, traditional art style, ${scenery}, black and white with subtle colors, calligraphy, masterpiece", "fields": [{"id": "scenery", "label": "景色", "type": "text", "placeholder": "例如：mountains, river, pine trees"}]}', 'image', 'chinese_style', 1500, 'system');
